```openscad
// Stand for 4 standard 1 cm spectrophotometer cuvettes
// Print orientation: base on XY plane at z = 0, building upward (+Z)

// ---------------- Block ----------------
block_x = 88;      // block length along X (mm)
block_y = 28;      // block width along Y (mm)
block_z = 25;      // block height (mm)

// ---------------- Pockets ----------------
pocket_count = 4;      // number of cuvette pockets
pocket_w     = 13.2;   // pocket size in X and Y (mm)
pocket_depth = 22;     // pocket depth from top face (mm)
pocket_pitch = 20.2;   // centre-to-centre spacing along X (mm)

// ---------------- Derived ----------------
floor_t   = block_z - pocket_depth;               // floor under pockets (3 mm)
overcut   = 0.5;                                  // extra cutter height past top face (mm)
row_start = -(pocket_count - 1) * pocket_pitch / 2; // X of first pocket centre

$fn = 64;

difference() {
    // Main block, centred in X and Y, sitting on z = 0
    translate([-block_x / 2, -block_y / 2, 0])
        cube([block_x, block_y, block_z]);

    // Row of square pockets opened from the top
    for (i = [0 : pocket_count - 1]) {
        translate([row_start + i * pocket_pitch - pocket_w / 2,
                   -pocket_w / 2,
                   floor_t])
            cube([pocket_w, pocket_w, pocket_depth + overcut]);
    }
}
```

