```openscad
// Horizontal pipette rest
// Units: mm. Print orientation: base plate on bed (z = 0), building +Z.

$fn = 96;

// ---- Base plate ----
base_len   = 140;   // plate length along X
base_wid   = 35;    // plate width along Y
base_thk   = 4;     // plate thickness (z = 0 to 4)

// ---- Uprights ----
up_thk     = 12;    // upright thickness along X
up_h       = 40;    // upright top height (z = 0 to 40)

// ---- Cradle notch ----
notch_r    = 10;    // semicircular notch radius, centre at (y=0, z=up_h)

// ---- Misc ----
eps        = 0.5;   // overshoot for clean boolean cuts

module upright(x0) {
    difference() {
        translate([x0, -base_wid/2, 0])
            cube([up_thk, base_wid, up_h]);
        // semicircular cradle running through the upright along X
        translate([x0 - eps, 0, up_h])
            rotate([0, 90, 0])
                cylinder(r = notch_r, h = up_thk + 2*eps);
    }
}

union() {
    // Base plate
    translate([-base_len/2, -base_wid/2, 0])
        cube([base_len, base_wid, base_thk]);

    // Uprights at each end, flush with plate ends
    for (x0 = [-base_len/2, base_len/2 - up_thk])
        upright(x0);
}
