```openscad
// Horizontal pipette rest
// Print orientation: base plate on the bed (z = 0), uprights build upward (+Z)

$fn = 96;               // curve resolution

// --- Base plate ---
base_len   = 120;       // plate length along X
base_wid   = 40;        // plate width along Y
base_thk   = 5;         // plate thickness along Z

// --- Uprights ---
up_thk     = 8;         // upright thickness along X
up_wid     = base_wid;  // upright width along Y (same as plate)
up_hgt     = 40;        // upright height, from z = 0 to top

// --- Cradle notch ---
notch_r    = 9;         // semicircular notch radius
notch_y    = 0;         // notch centre Y (on the top edge)
notch_z    = up_hgt;    // notch centre Z (on the top edge)

eps        = 0.5;       // overshoot for clean boolean cuts

// Upright X positions: flush with each plate end
up_x_pos = [ -base_len/2 + up_thk/2,  base_len/2 - up_thk/2 ];

module upright(xc) {
    difference() {
        // upright block
        translate([xc - up_thk/2, -up_wid/2, 0])
            cube([up_thk, up_wid, up_hgt]);
        // semicircular cradle running through along X
        translate([xc - up_thk/2 - eps, notch_y, notch_z])
            rotate([0, 90, 0])
                cylinder(r = notch_r, h = up_thk + 2*eps);
    }
}

union() {
    // base plate
    translate([-base_len/2, -base_wid/2, 0])
        cube([base_len, base_wid, base_thk]);

    // uprights at both ends
    for (xc = up_x_pos)
        upright(xc);
}
