// Horizontal pipette rest
// Print orientation: base plate on the bed (z = 0), uprights build upward.

// ---------- Parameters ----------
base_len      = 180;   // base plate length along X
base_wid      = 30;    // base plate width along Y
base_thk      = 4;     // base plate thickness (Z)

upright_thk   = 8;     // upright thickness along X
upright_h     = 30;    // upright total height from z = 0
cradle_r      = 9;     // radius of semicircular cradle notch

eps           = 0.5;   // cutter overshoot past faces
$fn           = 96;    // curve resolution

// ---------- Derived ----------
upright_x = [-base_len/2 + upright_thk/2,   // left end, flush
              base_len/2 - upright_thk/2];  // right end, flush

// ---------- Model ----------
union() {
    // Base plate
    translate([-base_len/2, -base_wid/2, 0])
        cube([base_len, base_wid, base_thk]);

    // Uprights with cradle notches
    for (x = upright_x)
        difference() {
            translate([x - upright_thk/2, -base_wid/2, 0])
                cube([upright_thk, base_wid, upright_h]);

            // Semicircular cradle: axis along X, centre at y = 0, z = upright_h
            translate([x - upright_thk/2 - eps, 0, upright_h])
                rotate([0, 90, 0])
                    cylinder(r = cradle_r, h = upright_thk + 2*eps);
        }
}
