```openscad
// Horizontal pipette rest
// Print orientation: base plate on bed (z = 0), uprights build upward (+Z)

$fn = 96;

// ---- Dimensions (mm) ----
base_len      = 120;  // base plate length (X)
base_wid      = 35;   // base plate width (Y)
base_thk      = 4;    // base plate thickness (Z)

upright_thk   = 8;    // upright thickness along X
upright_h     = 30;   // upright top height (from z = 0)

cradle_r      = 10;   // radius of semicircular cradle notch
cradle_z      = upright_h; // cradle centre height (on top edge)

eps           = 0.5;  // overshoot for clean boolean cuts

// ---- Model ----
difference() {
    union() {
        // Base plate
        translate([-base_len/2, -base_wid/2, 0])
            cube([base_len, base_wid, base_thk]);

        // Uprights, flush with each end of the plate
        for (s = [-1, 1])
            translate([s > 0 ? base_len/2 - upright_thk : -base_len/2,
                       -base_wid/2, 0])
                cube([upright_thk, base_wid, upright_h]);
    }

    // Cradle notches: cylinder axis along X, centre at y = 0, z = 30
    for (s = [-1, 1])
        translate([s * (base_len/2 - upright_thk/2), 0, cradle_z])
            rotate([0, 90, 0])
                cylinder(r = cradle_r, h = upright_thk + 2*eps, center = true);
}
```

