```openscad
// Flat hex-cap wrench for reagent bottles
// Print orientation: flat on bed, z = 0 to plate_t

// ---------------- Parameters ----------------
plate_t      = 5;     // plate thickness (Z)
head_d       = 40;    // round head diameter, centred on origin
handle_w     = 18;    // handle width (Y), centred on y = 0
handle_x0    = 0;     // handle start (X)
handle_x1    = 120;   // handle end (X)
hex_af       = 22;    // hex hole size across flats
eps          = 0.5;   // cutter overshoot past faces

// Derived
hex_r = (hex_af / 2) / cos(30);   // hex circumradius (corner radius)

// ---------------- Model ----------------
difference() {
    union() {
        // Round head
        cylinder(d = head_d, h = plate_t, $fn = 128);

        // Straight handle
        translate([handle_x0, -handle_w / 2, 0])
            cube([handle_x1 - handle_x0, handle_w, plate_t]);
    }

    // Hexagonal hole: $fn=6 puts corners on +/-X,
    // so two flats are parallel to the X axis (at y = +/- hex_af/2)
    translate([0, 0, -eps])
        cylinder(r = hex_r, h = plate_t + 2 * eps, $fn = 6);
}
```

```openscad
// Flat hex-cap wrench for reagent bottles
// Print orientation: flat on bed, z = 0 to plate_t

// ---------------- Parameters ----------------
plate_t      = 8;     // plate thickness (Z)
head_d       = 50;    // round head diameter
handle_w     = 16;    // handle width (Y)
handle_x0    = 0;     // handle start (X)
handle_x1    = 90;    // handle end (X)
hex_af       = 24;    // hex hole size across flats
eps          = 0.5;   // cut overshoot past faces

$fn = 128;

// Hex circumradius from across-flats size
hex_r = hex_af / sqrt(3);

// ---------------- Model ----------------
difference() {
    union() {
        // Round head centred on origin
        cylinder(d = head_d, h = plate_t);

        // Straight handle along +X
        translate([handle_x0, -handle_w / 2, 0])
            cube([handle_x1 - handle_x0, handle_w, plate_t]);
    }

    // Hexagonal hole: vertices on the X axis, so two flats are parallel to X
    translate([0, 0, -eps])
        linear_extrude(height = plate_t + 2 * eps)
            polygon([for (i = [0:5]) [hex_r * cos(60 * i), hex_r * sin(60 * i)]]);
}
