// Hex key organiser block
// Print orientation: base on z = 0, pockets open at the top

// ---- Block dimensions ----
block_l = 70;     // length along X
block_w = 18;     // width along Y
block_h = 20;     // height along Z

// ---- Pocket parameters ----
pocket_depth  = 12;                            // depth from top face
pocket_pitch  = 10;                            // centre-to-centre spacing along X
pocket_flats  = [1.9, 2.4, 2.9, 3.4, 4.4, 5.4]; // across-flats sizes, -X to +X
pocket_count  = len(pocket_flats);             // number of pockets
overcut       = 0.5;                           // extension past the top face

// x position of the first pocket, so the row is centred on the block
x_start = -pocket_pitch * (pocket_count - 1) / 2;

// Circumradius of a hexagon from its across-flats size
function hex_r(flats) = (flats / 2) / cos(30);

difference() {
    // Main block, centred in X and Y, standing on z = 0
    translate([-block_l / 2, -block_w / 2, 0])
        cube([block_l, block_w, block_h]);

    // Hexagonal pockets ($fn = 6 places vertices on the X axis,
    // so two flats are parallel to the X axis)
    for (i = [0 : pocket_count - 1])
        translate([x_start + i * pocket_pitch, 0, block_h - pocket_depth])
            cylinder(r = hex_r(pocket_flats[i]),
                     h = pocket_depth + overcut,
                     $fn = 6);
}
