    cylinder(d = outer_diameter, h = ring_thickness);

    // Central bore
    translate([0, 0, -overcut])
        cylinder(d = inner_diameter, h = ring_thickness + 2 * overcut);

    // Evenly spaced through-holes
    for (i = [0 : hole_count - 1]) {
        a = hole_start_angle + i * 360 / hole_count;
        translate([hole_pcd / 2 * cos(a), hole_pcd / 2 * sin(a), -overcut])
            cylinder(d = hole_diameter, h = ring_thickness + 2 * overcut);
    }
}
