// Microplate riser
// Print orientation: legs down on the bed (z = 0), top plate at z = 36..40

// ---------------- Parameters ----------------
plate_x      = 130;   // top plate length (X)
plate_y      = 100;   // top plate width (Y)
plate_t      = 4;     // top plate thickness
top_z        = 40;    // height of top face of plate

leg_size     = 12;    // square leg side length (X and Y)

window_x     = 86;    // central window length (X)
window_y     = 56;    // central window width (Y)

eps          = 0.5;   // cutting overlap to avoid coplanar faces
join         = 0.01;  // small overlap so legs fuse with plate

// Derived
plate_bot_z  = top_z - plate_t;   // underside of top plate (36)
leg_h        = plate_bot_z;       // legs run z = 0 to underside of plate

// ---------------- Model ----------------
union() {
    // Top plate with central window
    difference() {
        translate([-plate_x/2, -plate_y/2, plate_bot_z])
            cube([plate_x, plate_y, plate_t]);

        translate([-window_x/2, -window_y/2, plate_bot_z - eps])
            cube([window_x, window_y, plate_t + 2*eps]);
    }

    // Four corner legs, flush with plate outer edges
    for (sx = [-1, 1], sy = [-1, 1])
        translate([
            sx > 0 ? plate_x/2 - leg_size : -plate_x/2,
            sy > 0 ? plate_y/2 - leg_size : -plate_y/2,
            0
        ])
            cube([leg_size, leg_size, leg_h + join]);
}
