window_x     = 96;    // central window length (X)
window_y     = 56;    // central window width (Y)

eps          = 0.5;   // overshoot for clean boolean cuts

// ---------- Derived ----------
plate_bot_z  = top_z - plate_t;   // underside of plate (leg height)
leg_h        = plate_bot_z;

// ---------- Model ----------
union() {
    // Top plate with central window
    difference() {
        translate([-plate_x/2, -plate_y/2, plate_bot_z])
            cube([plate_x, plate_y, plate_t]);

        translate([-window_x/2, -window_y/2, plate_bot_z - eps])
            cube([window_x, window_y, plate_t + 2*eps]);
    }

    // Four corner legs, flush with the plate's outer edges.
    // Legs run up to z = 56.01 so they overlap the plate slightly
    // and fuse into a single solid.
    for (sx = [-1, 1], sy = [-1, 1])
        translate([sx > 0 ? plate_x/2 - leg_size : -plate_x/2,
                   sy > 0 ? plate_y/2 - leg_size : -plate_y/2,
                   0])
            cube([leg_size, leg_size, leg_h + 0.01]);
}
