// Wall mounting strip with countersunk screw holes
// Print orientation: flat on bed, countersinks facing up (+Z)

$fn = 64;

// ---- Bar dimensions ----
bar_length = 230;   // X length (mm)
bar_width  = 24;    // Y width (mm)
bar_thick  = 6;     // Z thickness (mm)

// ---- Screw holes ----
hole_count   = 5;     // number of screw holes
hole_pitch   = 50;    // spacing between hole centres along X (mm)
hole_d       = 4.5;   // through-hole diameter (mm)
csk_d        = 9;     // countersink diameter at top surface (mm)
csk_angle    = 90;    // countersink included angle (deg)

// ---- Derived ----
csk_depth = (csk_d - hole_d) / 2 / tan(csk_angle / 2); // depth of cone from top face
eps       = 0.5;    // overcut past faces to avoid coplanar surfaces

module countersunk_hole() {
    // Through-hole
    translate([0, 0, -eps])
        cylinder(h = bar_thick + 2 * eps, d = hole_d);
    // 90-degree countersink cone, extended eps above the top face
    // (radius grows by eps*tan(angle/2) to keep the same cone angle)
    translate([0, 0, bar_thick - csk_depth])
        cylinder(h = csk_depth + eps,
                 r1 = hole_d / 2,
                 r2 = csk_d / 2 + eps * tan(csk_angle / 2));
}

difference() {
    // Bar, centred in X and Y, resting on z = 0
    translate([-bar_length / 2, -bar_width / 2, 0])
        cube([bar_length, bar_width, bar_thick]);

    // Hole row centred on the bar along X at y = 0
    for (i = [0 : hole_count - 1])
        translate([(i - (hole_count - 1) / 2) * hole_pitch, 0, 0])
            countersunk_hole();
}
