// Tubing organiser - flat plate with notches along +Y edge
// Units: mm. Print orientation: flat on bed, z = 0 up.

$fn = 64;

// ---- Plate ----
plate_len   = 78;   // X length
plate_wid   = 24;   // Y width
plate_thk   = 4;    // Z thickness

// ---- Notches ----
notch_count = 4;    // number of notches
notch_w     = 8;    // notch width (X)
notch_d     = 12;   // notch depth into plate (along -Y)
notch_pitch = 18;   // centre-to-centre spacing (X)

// ---- Cutting overshoot ----
eps = 0.5;          // extension past cut faces

difference() {
    // Base plate, centred in X/Y, resting on z = 0
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Notches along +Y edge, centred along X
    for (i = [0 : notch_count - 1]) {
        x_c = (i - (notch_count - 1)/2) * notch_pitch;
        translate([x_c - notch_w/2,
                   plate_wid/2 - notch_d,
                   -eps])
            cube([notch_w, notch_d + eps, plate_thk + 2*eps]);
    }
}
