notch_w     = 4;    // notch width along X
notch_d     = 14;   // notch depth into plate along -Y
notch_pitch = 12;   // centre-to-centre spacing along X

// --- Cutting overshoot ---
eps = 0.5;          // extension past cut faces to avoid coplanar faces

// Derived: X position of first notch centre (notch group centred on X)
notch_x0 = -(notch_count - 1) * notch_pitch / 2;

difference() {
    // Base plate centred on origin in X and Y
    translate([-plate_len / 2, -plate_wid / 2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Notches cut from the +Y edge, through full thickness
    for (i = [0 : notch_count - 1]) {
        translate([notch_x0 + i * notch_pitch - notch_w / 2,
                   plate_wid / 2 - notch_d,
                   -eps])
            cube([notch_w, notch_d + eps, plate_thk + 2 * eps]);
    }
}
