// Tubing reel - printed lying on the bottom flange
$fn = 128;

flange_d   = 50;   // flange diameter
flange_t   = 3;    // flange thickness
core_d     = 25;   // core diameter
core_h     = 20;   // core height (z = 3 to z = 23)
bore_d     = 6;    // central through-bore diameter
eps        = 0.5;  // cut overshoot

total_h = flange_t + core_h + flange_t; // 26 mm

difference() {
    union() {
        // bottom flange
        cylinder(d = flange_d, h = flange_t);
        // core (slightly overlapped into flanges for clean union)
        translate([0, 0, flange_t - 0.01])
            cylinder(d = core_d, h = core_h + 0.02);
        // top flange
        translate([0, 0, flange_t + core_h])
            cylinder(d = flange_d, h = flange_t);
    }
    // central bore
    translate([0, 0, -eps])
        cylinder(d = bore_d, h = total_h + 2 * eps);
}
