        translate([0, 0, core_z0 - 0.01])
            cylinder(d = core_d, h = (core_z1 - core_z0) + 0.02);
        // top flange
        translate([0, 0, top_flange_z0])
            cylinder(d = flange_d, h = total_h - top_flange_z0);
    }
    // central bore through entire part
    translate([0, 0, -eps])
        cylinder(d = bore_d, h = total_h + 2 * eps);
}
